@prefix ada: <https://ada.astromat.org/metadata/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ada:L2MSCube ;
                    ada:ionizationTimeDelay 500 ;
                    ada:massGate true ;
                    ada:photoionizationWavelength 266 ;
                    ada:plasmaShutter false ;
                    ada:sampleName "Murchison_CM2_grain01" ;
                    ada:timeDelayUnits "nanoseconds" ;
                    ada:wavelengthUnits "nm" ] ;
            sh:resultMessage "L2MS detail nodes must declare ada:componentType." ;
            sh:resultPath ada:componentType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "L2MS detail nodes must declare ada:componentType." ;
                    sh:minCount 1 ;
                    sh:path ada:componentType ] ] .
